4	import { useSyncExternalStore } from "react";
5	import { CalendarIcon } from "./icons";
6	
7	const subscribe = () => () => {};
8	/** Today as YYYY-MM-DD in the viewer's time zone. */
9	const getToday = () => {
10	  const d = new Date();
11	  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
12	};
13	// The server doesn't know the viewer's time zone, so relative labels appear only after hydration.
14	const getServerToday = () => null;
15	
16	const formatter = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
17	const DAY_MS = 86_400_000;
18	
19	function relative(due: string, today: string) {
20	  const days = Math.round((Date.parse(due) - Date.parse(today)) / DAY_MS);
21	  if (days < 0) return { label: days === -1 ? "1 day overdue" : `${-days} days overdue`, tone: "overdue" };
22	  if (days === 0) return { label: "Due today", tone: "soon" };
23	  if (days === 1) return { label: "Due tomorrow", tone: "soon" };
24	  if (days < 7) return { label: `In ${days} days`, tone: "" };
25	  return null;
26	}
27	
28	export function DueDate({ date, done }: { date: string; done: boolean }) {
29	  const today = useSyncExternalStore(subscribe, getToday, getServerToday);
30	  const parsed = Date.parse(date);
31	  const rel = today && !done ? relative(date, today) : null;
32	
33	  return (
34	    <span className={`due${rel?.tone ? ` due-${rel.tone}` : ""}`}>
35	      <CalendarIcon />
36	      <time dateTime={date}>{Number.isNaN(parsed) ? date : formatter.format(parsed)}</time>
37	      {rel ? <span className="due-rel">{rel.label}</span> : null}
38	    </span>
39	  );
40	}
