244	function RejectedTable({
245	  headers,
246	  rejected,
247	  fileName,
248	}: {
249	  headers: string[];
250	  rejected: RejectedRow[];
251	  fileName?: string;
252	}) {
253	  const titleIndex = headers.findIndex((h) => h.toLowerCase() === "title");
254	
255	  function download() {
256	    const csv = buildRejectsCsv(headers, rejected);
257	    // Prepend a BOM so Excel opens the UTF-8 file with the right encoding.
258	    const url = URL.createObjectURL(new Blob(["﻿", csv], { type: "text/csv;charset=utf-8" }));
259	    const link = document.createElement("a");
260	    link.href = url;
261	    link.download = `${(fileName ?? "import").replace(/\.csv$/i, "")}-rejected.csv`;
262	    link.click();
263	    // Revoking straight away can cancel the download in Safari and some Firefox setups.
264	    setTimeout(() => URL.revokeObjectURL(url), 10_000);
265	  }
266	
267	  return (
268	    <>
269	      <div className="row section-head">
270	        <h3>Rejected rows</h3>
271	        <button type="button" className="secondary" onClick={download}>
272	          <DownloadIcon /> Download rejected rows (CSV)
273	        </button>
274	      </div>
275	      <div className="table-wrap">
276	      <table>
277	        <thead>
278	          <tr>
279	            <th scope="col">Row</th>
280	            <th scope="col">Title</th>
281	            <th scope="col">Reason</th>
282	          </tr>
283	        </thead>
284	        <tbody>
285	          {rejected.map((row) => {
286	            const title = titleIndex === -1 ? "" : (row.cells[titleIndex] ?? "").trim();
287	            // Count code points, as validation does, so an emoji is never cut in half.
288	            const chars = Array.from(title);
