295	                  ) : chars.length > PREVIEW_LENGTH ? (
296	                    `${chars.slice(0, PREVIEW_LENGTH).join("")}…`
297	                  ) : (
298	                    title
299	                  )}
300	                </td>
301	                <td>
302	                  <ul className="reasons">
